<style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:#f3f6f8;color:#172033}.wrap{max-width:1320px;margin:24px auto;padding:0 18px}.top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:18px}.top h1{margin:0;color:#102a43}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:9px;padding:10px 14px;background:#102a43;color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.btn.green{background:#0f766e}.btn.light{background:#fff;color:#102a43;border:1px solid #cbd5e1}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.metric,.card{background:#fff;border:1px solid #dde6ed;border-radius:14px;box-shadow:0 5px 18px rgba(15,23,42,.04)}.metric{padding:16px}.metric strong{font-size:29px;color:#0f766e}.metric span{display:block;color:#64748b;font-size:12px;text-transform:uppercase;font-weight:800;letter-spacing:.04em}.card{padding:18px;margin-bottom:18px}.card h2{margin:0 0 14px;color:#102a43;font-size:21px}.muted{color:#64748b;font-size:13px}.forms{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.formgrid .wide{grid-column:1/-1}.field label{display:block;font-size:12px;font-weight:800;color:#52677a;margin-bottom:5px;text-transform:uppercase}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.check{display:flex;gap:7px;align-items:center;margin-top:8px;font-size:13px}.check input{width:auto}.section-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:26px 0 10px}.section-title h2{margin:0;color:#102a43}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:880px}.table th,.table td{padding:10px;border-bottom:1px solid #e5eaf0;text-align:left;vertical-align:top;font-size:13px}.table th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc}.inline{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.inline input,.inline select{padding:7px;border:1px solid #cbd5e1;border-radius:7px;max-width:160px}.smallbtn{border:0;border-radius:7px;padding:7px 9px;background:#334155;color:#fff;cursor:pointer}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#e2e8f0;font-size:11px;font-weight:800}.badge.on{background:#d1fae5;color:#065f46}.badge.off{background:#fee2e2;color:#991b1b}.alert{padding:12px 14px;border-radius:9px;margin-bottom:14px}.success{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}.seat-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(105px,1fr));gap:8px;margin-top:10px}.seat-chip{border:1px solid #dbe4eb;border-radius:9px;padding:9px;background:#f8fafc}.seat-chip.off{opacity:.5}.seat-chip strong{display:block}.pagination{margin-top:12px}@media(max-width:900px){.grid4,.forms{grid-template-columns:1fr 1fr}}@media(max-width:650px){.grid4,.forms,.formgrid{grid-template-columns:1fr}.formgrid .wide{grid-column:auto}.top{flex-direction:column}}
</style>
