<div class="card"><h2>Add Seat</h2><form method="POST" action="{{ route('admin.study-space.seats.store') }}">@csrf<div class="formgrid"><div class="field wide"><label>Study Hall</label><select name="study_hall_id" required>@foreach($halls as $h)<option value="{{ $h->id }}">{{ $h->name }} · Branch #{{ $h->branch_id }}</option>@endforeach</select></div><div class="field"><label>Seat Number</label><input name="seat_no" required placeholder="A-01"></div><div class="field"><label>Seat Type</label><input name="seat_type" placeholder="Standard / Premium"></div></div><label class="check"><input type="checkbox" name="status" value="1" checked> Available for allocation</label><div style="margin-top:12px"><button class="btn green">Add Seat</button></div></form></div>

<div class="card"><h2>Create Study Slot</h2><form method="POST" action="{{ route('admin.study-space.slots.store') }}">@csrf<div class="formgrid"><div class="field"><label>Branch</label><select name="branch_id" required>@foreach($branches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select></div><div class="field"><label>Slot Name</label><input name="name" required placeholder="Morning 4 Hours"></div><div class="field"><label>Duration Hours</label><select name="duration_hours" required>@foreach([3,4,6,8,10,12,24] as $h)<option value="{{ $h }}">{{ $h }} Hours</option>@endforeach</select></div><div class="field"><label>Start Time</label><input type="time" name="start_time"></div><div class="field"><label>End Time</label><input type="time" name="end_time"></div></div><div class="inline"><label class="check"><input type="checkbox" name="is_flexible" value="1"> Flexible</label><label class="check"><input type="checkbox" name="is_24x7" value="1"> 24×7</label><label class="check"><input type="checkbox" name="status" value="1" checked> Active</label></div><div style="margin-top:12px"><button class="btn green">Create Slot</button></div></form></div>

<div class="card"><h2>Create Fee Plan</h2><form method="POST" action="{{ route('admin.study-space.plans.store') }}">@csrf<div class="formgrid"><div class="field"><label>Branch</label><select name="branch_id" required>@foreach($branches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select></div><div class="field"><label>Study Slot</label><select name="study_slot_id" required>@foreach($slots as $s)<option value="{{ $s->id }}">{{ $s->name }} ({{ $s->duration_hours }}h)</option>@endforeach</select></div><div class="field wide"><label>Plan Name</label><input name="name" required placeholder="4 Hour Monthly Plan"></div><div class="field"><label>Monthly Fee</label><input type="number" step="0.01" min="0" name="monthly_fee" required></div><div class="field"><label>Validity Days</label><input type="number" min="1" name="validity_days" value="30" required></div><div class="field"><label>Admission Fee</label><input type="number" step="0.01" min="0" name="admission_fee"></div><div class="field"><label>Registration Fee</label><input type="number" step="0.01" min="0" name="registration_fee"></div><div class="field"><label>Quarterly Fee</label><input type="number" step="0.01" min="0" name="quarterly_fee"></div><div class="field"><label>Half Yearly Fee</label><input type="number" step="0.01" min="0" name="half_yearly_fee"></div><div class="field"><label>Yearly Fee</label><input type="number" step="0.01" min="0" name="yearly_fee"></div><div class="field"><label>Security Deposit</label><input type="number" step="0.01" min="0" name="security_deposit"></div><div class="field"><label>Late Fee</label><input type="number" step="0.01" min="0" name="late_fee"></div></div><label class="check"><input type="checkbox" name="status" value="1" checked> Active</label><div style="margin-top:12px"><button class="btn green">Create Plan</button></div></form></div>
</div>

<div class="section-title"><h2>Allocate Seat to Student</h2><span class="muted">System blocks overlapping allocation on the same seat.</span></div>
<div class="card"><form method="POST" action="{{ route('admin.study-space.allocations.store') }}">@csrf<div class="formgrid"><div class="field"><label>Student</label><select name="student_id" required><option value="">Select Student</option>@foreach($students as $s)<option value="{{ $s->id }}">{{ $s->student_code }} · {{ $s->name }} · {{ $s->mobile }}</option>@endforeach</select></div><div class="field"><label>Seat</label><select name="seat_id" required><option value="">Select Seat</option>@foreach($halls as $h)@foreach($h->seats->where('status',true) as $seat)<option value="{{ $seat->id }}">{{ $h->name }} · Seat {{ $seat->seat_no }}</option>@endforeach @endforeach</select></div><div class="field"><label>Study Slot</label><select name="study_slot_id" required>@foreach($slots->where('status',true) as $slot)<option value="{{ $slot->id }}">{{ $slot->name }} · {{ $slot->duration_hours }}h</option>@endforeach</select></div><div class="field"><label>Status</label><select name="status"><option value="active">Active</option><option value="reserved">Reserved</option></select></div><div class="field"><label>From</label><input type="date" name="allocated_from" value="{{ now()->toDateString() }}" required></div><div class="field"><label>To</label><input type="date" name="allocated_to" value="{{ now()->addDays(29)->toDateString() }}"></div><div class="field wide"><label>Remarks</label><textarea name="remarks" rows="2" placeholder="Optional allocation note"></textarea></div></div><div style="margin-top:12px"><button class="btn green">Allocate Seat</button></div></form></div>

<div class="section-title"><h2>Study Halls & Seats</h2></div>
@forelse($halls as $hall)<div class="card"><div class="inline" style="justify-content:space-between"><div><strong style="font-size:18px">{{ $hall->name }}</strong><div class="muted">Floor: {{ $hall->floor ?: '—' }} · {{ $hall->seats_count }} seats · <span class="badge {{ $hall->status?'on':'off' }}">{{ $hall->status?'Active':'Disabled' }}</span></div></div><form class="inline" method="POST" action="{{ route('admin.study-space.halls.update',$hall) }}">@csrf @method('PATCH')<input name="name" value="{{ $hall->name }}" required><input name="floor" value="{{ $hall->floor }}" placeholder="Floor"><input type="number" min="1" name="total_seats" value="{{ $hall->total_seats }}" required><label class="check"><input type="checkbox" name="status" value="1" @checked($hall->status)> Active</label><button class="smallbtn">Save Hall</button></form></div><div class="seat-grid">@forelse($hall->seats as $seat)<div class="seat-chip {{ $seat->status?'':'off' }}"><strong>{{ $seat->seat_no }}</strong><span class="muted">{{ $seat->seat_type ?: 'Standard' }}</span><form class="inline" style="margin-top:6px" method="POST" action="{{ route('admin.study-space.seats.update',$seat) }}">@csrf @method('PATCH')<input name="seat_no" value="{{ $seat->seat_no }}" style="width:62px"><input name="seat_type" value="{{ $seat->seat_type }}" style="width:90px"><label class="check"><input type="checkbox" name="status" value="1" @checked($seat->status)> On</label><button class="smallbtn">Save</button></form></div>@empty<div class="muted">No seats added yet.</div>@endforelse</div></div>@empty<div class="card muted">No study halls configured yet.</div>@endforelse

<div class="section-title"><h2>Study Slots</h2></div><div class="card tablewrap"><table class="table"><thead><tr><th>Name</th><th>Duration</th><th>Timing</th><th>Type</th><th>Status</th><th>Edit</th></tr></thead><tbody>@forelse($slots as $slot)<tr><td>{{ $slot->name }}</td><td>{{ $slot->duration_hours }}h</td><td>{{ $slot->start_time ? substr($slot->start_time,0,5) : '—' }} – {{ $slot->end_time ? substr($slot->end_time,0,5) : '—' }}</td><td>{{ $slot->is_24x7?'24×7':($slot->is_flexible?'Flexible':'Fixed') }}</td><td><span class="badge {{ $slot->status?'on':'off' }}">{{ $slot->status?'Active':'Disabled' }}</span></td><td><form class="inline" method="POST" action="{{ route('admin.study-space.slots.update',$slot) }}">@csrf @method('PATCH')<input name="name" value="{{ $slot->name }}"><input type="number" min="1" max="24" name="duration_hours" value="{{ $slot->duration_hours }}" style="width:65px"><input type="time" name="start_time" value="{{ $slot->start_time ? substr($slot->start_time,0,5) : '' }}"><input type="time" name="end_time" value="{{ $slot->end_time ? substr($slot->end_time,0,5) : '' }}"><label class="check"><input type="checkbox" name="is_flexible" value="1" @checked($slot->is_flexible)> Flex</label><label class="check"><input type="checkbox" name="is_24x7" value="1" @checked($slot->is_24x7)> 24×7</label><label class="check"><input type="checkbox" name="status" value="1" @checked($slot->status)> On</label><button class="smallbtn">Save</button></form></td></tr>@empty<tr><td colspan="6">No slots configured.</td></tr>@endforelse</tbody></table></div>

<div class="section-title"><h2>Fee Plans</h2></div><div class="card tablewrap"><table class="table"><thead><tr><th>Plan</th><th>Slot</th><th>Monthly</th><th>Validity</th><th>Status</th><th>Edit</th></tr></thead><tbody>@forelse($plans as $plan)<tr><td>{{ $plan->name }}</td><td>{{ $plan->studySlot?->name }}</td><td>₹{{ number_format((float)$plan->monthly_fee,2) }}</td><td>{{ $plan->validity_days }} days</td><td><span class="badge {{ $plan->status?'on':'off' }}">{{ $plan->status?'Active':'Disabled' }}</span></td><td><form class="inline" method="POST" action="{{ route('admin.study-space.plans.update',$plan) }}">@csrf @method('PATCH')<select name="study_slot_id">@foreach($slots->where('branch_id',$plan->branch_id) as $s)<option value="{{ $s->id }}" @selected($s->id===$plan->study_slot_id)>{{ $s->name }}</option>@endforeach</select><input name="name" value="{{ $plan->name }}"><input type="number" step="0.01" min="0" name="monthly_fee" value="{{ $plan->monthly_fee }}"><input type="number" min="1" name="validity_days" value="{{ $plan->validity_days }}"><input type="hidden" name="quarterly_fee" value="{{ $plan->quarterly_fee }}"><input type="hidden" name="half_yearly_fee" value="{{ $plan->half_yearly_fee }}"><input type="hidden" name="yearly_fee" value="{{ $plan->yearly_fee }}"><input type="hidden" name="admission_fee" value="{{ $plan->admission_fee }}"><input type="hidden" name="registration_fee" value="{{ $plan->registration_fee }}"><input type="hidden" name="security_deposit" value="{{ $plan->security_deposit }}"><input type="hidden" name="late_fee" value="{{ $plan->late_fee }}"><label class="check"><input type="checkbox" name="status" value="1" @checked($plan->status)> On</label><button class="smallbtn">Save</button></form></td></tr>@empty<tr><td colspan="6">No fee plans configured.</td></tr>@endforelse</tbody></table></div>

<div class="section-title"><h2>Seat Allocations</h2></div><div class="card tablewrap"><table class="table"><thead><tr><th>Student</th><th>Hall / Seat</th><th>Slot</th><th>Period</th><th>Status</th><th>Update</th></tr></thead><tbody>@forelse($allocations as $a)<tr><td><strong>{{ $a->student?->name }}</strong><div class="muted">{{ $a->student?->student_code }}</div></td><td>{{ $a->seat?->studyHall?->name }} · {{ $a->seat?->seat_no }}</td><td>{{ $a->studySlot?->name }}<div class="muted">{{ $a->studySlot?->duration_hours }}h</div></td><td>{{ $a->allocated_from?->format('d M Y') }} – {{ $a->allocated_to?->format('d M Y') ?? 'Open' }}</td><td><span class="badge {{ in_array($a->status,['active','reserved'])?'on':'off' }}">{{ ucfirst($a->status) }}</span></td><td><form class="inline" method="POST" action="{{ route('admin.study-space.allocations.update',$a) }}">@csrf @method('PATCH')<select name="status"><option value="reserved" @selected($a->status==='reserved')>Reserved</option><option value="active" @selected($a->status==='active')>Active</option><option value="completed" @selected($a->status==='completed')>Completed</option><option value="cancelled" @selected($a->status==='cancelled')>Cancelled</option></select><input type="date" name="allocated_to" value="{{ $a->allocated_to?->format('Y-m-d') }}"><input name="remarks" value="{{ $a->remarks }}" placeholder="Remarks"><button class="smallbtn">Update</button></form></td></tr>@empty<tr><td colspan="6">No seat allocations yet.</td></tr>@endforelse</tbody></table><div class="pagination">{{ $allocations->links() }}</div></div>
</div>
